<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#17211b"><link rel="manifest" href="/manifest.webmanifest"><title>NearWave — Meet People Nearby</title><style>body{margin:0;font-family:Inter,system-ui,sans-serif;background:#f4f6f1;color:#17211b}*{box-sizing:border-box}.landing{min-height:100vh;display:grid;place-items:center;text-align:center;padding:32px}.card{max-width:600px}.mark{width:58px;height:58px;background:#17211b;color:#fff;border-radius:18px;display:grid;place-items:center;margin:auto;font-size:28px;font-weight:800}.eyebrow{font-size:11px;letter-spacing:.16em;color:#71806d;font-weight:800}.landing h1{font-size:clamp(48px,9vw,84px);line-height:.95;letter-spacing:-.06em;margin:18px 0}.landing h1 span{color:#718d64}.lead{color:#667166;line-height:1.7}.btn{display:inline-flex;gap:8px;padding:14px 20px;border:0;border-radius:12px;background:#17211b;color:#fff;font-weight:800;cursor:pointer;margin:10px 4px}.install{position:fixed;left:16px;right:16px;bottom:16px;background:#17211b;color:white;border-radius:16px;padding:14px 16px;display:none;align-items:center;gap:12px;box-shadow:0 14px 40px #0003;z-index:50}.install button{margin-left:auto;border:0;border-radius:9px;padding:9px 13px;font-weight:800}.app{display:none;min-height:100vh}.top{height:68px;background:#fff;border-bottom:1px solid #dde3d9;display:flex;align-items:center;justify-content:space-between;padding:0 18px;position:sticky;top:0;z-index:10}.brand{font-weight:800}.wrap{max-width:1050px;margin:auto;padding:24px 16px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.people{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.person,.row{background:#fff;border:1px solid #dde3d9;border-radius:16px;padding:14px}.person{display:grid;grid-template-columns:54px 1fr;gap:12px}.person img{width:54px;height:54px;border-radius:14px;object-fit:cover}.person h3{margin:0 0 4px;font-size:15px}.muted{color:#7a8479;font-size:12px}.wave{grid-column:1/-1;width:100%;border:0;background:#e8efe4;padding:10px;border-radius:10px;font-weight:800;cursor:pointer}.section{margin-top:35px}.row{display:flex;align-items:center;gap:10px;margin:8px 0}.row .grow{flex:1}.row button{border:0;border-radius:9px;padding:9px;cursor:pointer}.accept{background:#dfedd9}.decline{background:#eee9e6}.chat{position:fixed;inset:0;background:#17211b55;display:none;place-items:center;padding:16px;z-index:30}.panel{width:min(500px,100%);height:min(650px,92vh);background:#fff;border-radius:20px;display:flex;flex-direction:column;overflow:hidden}.chathead{padding:14px;border-bottom:1px solid #dde3d9;display:flex;gap:10px;align-items:center}.msgs{flex:1;overflow:auto;padding:16px}.msg{background:#e8eee5;padding:9px 12px;border-radius:13px;margin:6px 0;max-width:75%;width:max-content}.mine{margin-left:auto;background:#17211b;color:#fff}.compose{display:flex;gap:8px;padding:10px;border-top:1px solid #dde3d9}.compose input{flex:1;padding:11px;border:1px solid #d8dfd5;border-radius:10px}.compose button{background:#17211b;color:#fff;border:0;border-radius:10px;padding:0 15px}@media(max-width:600px){.landing h1{font-size:54px}}</style></head><body><section id="landing" class="landing"><div class="card"><div class="mark">N</div><p class="eyebrow">PROXIMITY • PRESENCE • CONNECTION</p><h1>Meet the people<br><span>around you.</span></h1><p class="lead">See nearby people who choose to be discoverable. Wave first. Chat only when they accept.</p><a class="btn" href="/auth/google/redirect">Continue with Google</a><a class="btn" href="/auth/apple/redirect">Apple</a><a class="btn" href="/auth/x/redirect">X</a></div></section><section id="app" class="app"><header class="top"><div class="brand">N NearWave</div><div><span id="status" class="muted">Location pending</span><button class="btn" style="padding:9px 12px" onclick="toggleVisibility()">Visibility</button><form style="display:inline" method="post" action="/logout"><input type="hidden" name="_token" value="{{csrf_token()}}"><button class="btn" style="padding:9px 12px;background:#eee;color:#17211b">Logout</button></form></div></header><main class="wrap"><p class="eyebrow">DISCOVER</p><h1>People nearby</h1><p id="notice" class="muted">Finding people around you…</p><div class="toolbar"><button class="btn" onclick="locate()">⌖ Refresh location</button></div><div id="people" class="people"></div><section class="section"><h2>Incoming waves</h2><div id="waves"></div></section><section class="section"><h2>Connections</h2><div id="connections"></div></section></main></section><div id="install" class="install"><div><b>Install NearWave</b><div style="font-size:12px;opacity:.75">Add NearWave to your home screen for a faster app experience.</div></div><button onclick="installApp()">Install</button><button onclick="dismissInstall()">×</button></div><div id="chat" class="chat"><div class="panel"><div class="chathead"><button onclick="closeChat()">←</button><b id="chatName">Chat</b></div><div id="msgs" class="msgs"></div><form class="compose" onsubmit="sendMessage(event)"><input id="message" maxlength="2000" placeholder="Write a message…"><button>Send</button></form></div></div><script>const csrf='{{csrf_token()}}';let deferredInstall=null,currentPeer=null;async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf};const r=await fetch(url,opt);if(!r.ok)throw new Error((await r.json().catch(()=>({}))).message||'Request failed');return r.json()}async function boot(){try{const n=await api('/api/nearby');document.getElementById('app').style.display='block';document.getElementById('landing').style.display='none';render(n.people||[]);document.getElementById('status').textContent=n.visible?'Visible nearby':'Hidden';locate();loadWaves();loadConnections()}catch(e){document.getElementById('app').style.display='block';document.getElementById('landing').style.display='none';locate()}}async function locate(){if(!navigator.geolocation){notice('Your browser does not support location.');return}notice('Finding people around you…');navigator.geolocation.getCurrentPosition(async p=>{try{const d=await api('/api/location',{method:'POST',body:JSON.stringify({latitude:p.coords.latitude,longitude:p.coords.longitude,visible:true})});render(d.people||[]);notice(`${(d.people||[]).length} people nearby`)}catch(e){notice(e.message)}},()=>notice('Please allow location access to discover people nearby.'),{enableHighAccuracy:false,maximumAge:30000,timeout:10000})}function notice(s){document.getElementById('notice').textContent=s}function render(ps){document.getElementById('people').innerHTML=ps.length?ps.map(p=>`<article class="person"><img src="${p.picture||'/favicon.ico'}"><div><h3>${esc(p.name)}</h3><span class="muted">${p.distance<1?'Less than 1 km':p.distance+' km'} away ${p.online?'• online':''}</span></div><button class="wave" onclick="wave(${p.id},this)">👋 Wave</button></article>`).join(''):'<div class="person" style="grid-column:1/-1"><div><h3>No one on your radar yet</h3><span class="muted">Keep this page open while other nearby users become visible.</span></div></div>'}async function wave(id,b){b.disabled=true;b.textContent='Sending…';try{await api('/api/waves',{method:'POST',body:JSON.stringify({to_user_id:id})});b.textContent='Wave sent 👋';b.style.opacity='.6'}catch(e){b.disabled=false;b.textContent='👋 Wave';notice(e.message)}}async function loadWaves(){try{const d=await api('/api/waves/incoming');document.getElementById('waves').innerHTML=(d.waves||[]).map(w=>`<div class="row"><div class="grow"><b>${esc(w.from_name)}</b><div class="muted">waved at you 👋</div></div><button class="accept" onclick="respond(${w.id},'accepted')">✓ Accept</button><button class="decline" onclick="respond(${w.id},'declined')">×</button></div>`).join('')||'<p class="muted">No incoming waves.</p>'}catch(e){}}async function respond(id,status){try{const d=await api('/api/waves/'+id+'/respond',{method:'POST',body:JSON.stringify({status})});notice(status==='accepted'?'Connected — chat is now available.':'Wave declined.');await loadWaves();await loadConnections()}catch(e){notice(e.message)}}async function loadConnections(){try{const d=await api('/api/connections');document.getElementById('connections').innerHTML=(d.people||[]).map(p=>`<button class="row" style="width:100%;text-align:left" onclick="openChat(${p.id},'${esc(p.name)}')"><b class="grow">${esc(p.name)}</b>💬</button>`).join('')||'<p class="muted">Accepted waves become private chats here.</p>'}catch(e){}}async function openChat(id,name){currentPeer=id;document.getElementById('chatName').textContent=name;document.getElementById('chat').style.display='grid';const d=await api('/api/chats/'+id);document.getElementById('msgs').innerHTML=(d.messages||[]).map(m=>`<div class="msg ${m.sender_id==={{auth()->id()??0}}?'mine':''}">${esc(m.body)}</div>`).join('')}function closeChat(){document.getElementById('chat').style.display='none'}async function sendMessage(e){e.preventDefault();const i=document.getElementById('message');if(!i.value.trim())return;try{await api('/api/chats/'+currentPeer+'/messages',{method:'POST',body:JSON.stringify({body:i.value})});i.value='';openChat(currentPeer,document.getElementById('chatName').textContent)}catch(e){notice(e.message)}}async function toggleVisibility(){const n=document.getElementById('status').textContent.includes('Visible');const d=await api('/api/visibility',{method:'POST',body:JSON.stringify({visible:!n})});document.getElementById('status').textContent=d.visible?'Visible nearby':'Hidden'}function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;document.getElementById('install').style.display='flex'});async function installApp(){if(deferredInstall){deferredInstall.prompt();deferredInstall=null}document.getElementById('install').style.display='none'}function dismissInstall(){localStorage.setItem('nw-install-dismissed','1');document.getElementById('install').style.display='none'}if(!localStorage.getItem('nw-install-dismissed')){}if({{auth()->check()?'true':'false'}})boot();</script></body></html>
